class FoxMarquee extends HTMLElement {
  #abortController = null;
  #animation = null;
  #inner = null;
  #resizeObserver = null;
  #resizeFallback = null;
  #setupFrame = null;
  #lastWidth = 0;
  #lastContainerWidth = 0;

  constructor() {
    super();

    const rawDirection = this.getAttribute('direction') || 'ltr';
    const isDocumentRtl = document.documentElement.dir === 'rtl';

    this.speed = 300 * this.#number(this.getAttribute('speed-factor'), 0.4);
    this.direction = isDocumentRtl
      ? rawDirection === 'ltr'
        ? 'rtl'
        : 'ltr'
      : rawDirection;
  }

  connectedCallback() {
    if (this.#inner) return;

    this.dataset.state = 'idle';

    if (!this.#collectElements()) {
      this.#setDisabled();
      return;
    }

    this.#bindEvents();
    this.#setup();
    this.#watchResize();
  }

  disconnectedCallback() {
    this.destroy();
  }

  play() {
    this.#animation?.play();
  }

  pause() {
    this.#animation?.pause();
  }

  refresh() {
    this.#queueSetup();
  }

  destroy() {
    const wasReady = this.dataset.state === 'ready';

    this.#abortController?.abort();
    this.#abortController = null;
    this.#resizeObserver?.disconnect();
    this.#resizeObserver = null;

    if (this.#resizeFallback) {
      window.removeEventListener('resize', this.#resizeFallback);
      this.#resizeFallback = null;
    }

    if (this.#setupFrame) {
      cancelAnimationFrame(this.#setupFrame);
      this.#setupFrame = null;
    }

    this.#animation?.cancel();
    this.#animation = null;
    this.#removeDuplicates();
    this.#inner = null;
    this.#lastWidth = 0;
    this.#lastContainerWidth = 0;
    this.dataset.state = 'idle';

    if (wasReady) {
      this.#emit('marquee:destroy', {});
    }
  }

  #collectElements() {
    this.#inner = this.querySelector('.fox-marquee__inner');

    if (this.#inner) return this.#getOriginalItems().length > 0;

    const directItems = Array.from(this.children).filter((child) =>
      child.classList?.contains('fox-marquee__item')
    );

    if (directItems.length === 0) return false;

    this.#inner = document.createElement('div');
    this.#inner.className = 'fox-marquee__inner';
    directItems.forEach((item) => this.#inner.appendChild(item));
    this.appendChild(this.#inner);

    return true;
  }

  #bindEvents() {
    this.#abortController?.abort();
    this.#abortController = new AbortController();

    const signal = this.#abortController.signal;

    if (this.hasAttribute('pausable')) {
      this.addEventListener('mouseenter', () => this.pause(), { signal });
      this.addEventListener('mouseleave', () => this.play(), { signal });
      this.addEventListener('focusin', () => this.pause(), { signal });
      this.addEventListener('focusout', () => this.play(), { signal });
    }

    const motionQuery = this.#motionQuery();
    const motionHandler = () => this.refresh();

    if (motionQuery?.addEventListener) {
      motionQuery.addEventListener('change', motionHandler, { signal });
    } else if (motionQuery?.addListener) {
      motionQuery.addListener(motionHandler);
      signal.addEventListener(
        'abort',
        () => motionQuery.removeListener(motionHandler),
        { once: true }
      );
    }
  }

  #watchResize() {
    if ('ResizeObserver' in window) {
      this.#resizeObserver = new ResizeObserver(() => this.#queueSetup());
      this.#resizeObserver.observe(this);
      if (this.#inner) this.#resizeObserver.observe(this.#inner);
      return;
    }

    this.#resizeFallback = () => this.#queueSetup();
    window.addEventListener('resize', this.#resizeFallback, { passive: true });
  }

  #queueSetup() {
    if (this.#setupFrame) return;

    this.#setupFrame = requestAnimationFrame(() => {
      this.#setupFrame = null;
      this.#setup();
    });
  }

  #setup() {
    if (!this.#inner) return;

    const originalItems = this.#getOriginalItems();
    const originalWidth = this.#getItemsWidth(originalItems);
    const containerWidth = this.offsetWidth;

    if (originalItems.length === 0 || originalWidth === 0) {
      this.#setDisabled();
      return;
    }

    if (
      this.#lastWidth === originalWidth &&
      this.#lastContainerWidth === containerWidth &&
      this.dataset.state === 'ready'
    ) {
      return;
    }

    this.#animation?.cancel();
    this.#animation = null;
    this.#removeDuplicates();
    this.#lastWidth = originalWidth;
    this.#lastContainerWidth = containerWidth;

    const clonesNeeded = Math.max(
      2,
      Math.ceil((containerWidth * 3) / originalWidth)
    );
    const fragment = document.createDocumentFragment();

    for (let index = 0; index < clonesNeeded; index += 1) {
      originalItems.forEach((item) => {
        const clone = item.cloneNode(true);

        clone.setAttribute('aria-hidden', 'true');
        clone.classList.add('fox-marquee__item--duplicate');
        clone
          .querySelectorAll('a, button, input, select, textarea, [tabindex]')
          .forEach((element) => {
            element.tabIndex = -1;
          });

        fragment.appendChild(clone);
      });
    }

    this.#inner.appendChild(fragment);
    this.dataset.state = 'ready';
    this.#emit('marquee:ready', {
      itemCount: originalItems.length,
      width: originalWidth,
    });

    if (this.#prefersReducedMotion()) return;

    const moveDistance = originalWidth;
    const duration = Math.max(1000, (moveDistance / this.speed) * 1000);
    const from = this.direction === 'rtl' ? '0px' : `-${moveDistance}px`;
    const to = this.direction === 'rtl' ? `-${moveDistance}px` : '0px';

    this.#animation = this.#inner.animate(
      [
        { transform: `translateX(${from}) translateZ(0)` },
        { transform: `translateX(${to}) translateZ(0)` },
      ],
      {
        duration,
        easing: 'linear',
        iterations: Infinity,
      }
    );
  }

  #getOriginalItems() {
    if (!this.#inner) return [];

    return Array.from(this.#inner.children).filter(
      (child) =>
        child.classList.contains('fox-marquee__item') &&
        !child.classList.contains('fox-marquee__item--duplicate')
    );
  }

  #getItemsWidth(items) {
    if (items.length === 0) return 0;

    const firstItem = items[0];
    const lastItem = items[items.length - 1];

    return lastItem.offsetLeft - firstItem.offsetLeft + lastItem.offsetWidth;
  }

  #removeDuplicates() {
    this.#inner
      ?.querySelectorAll('.fox-marquee__item--duplicate')
      .forEach((item) => item.remove());
  }

  #setDisabled() {
    this.#animation?.cancel();
    this.#animation = null;
    this.dataset.state = 'disabled';
  }

  #prefersReducedMotion() {
    return Boolean(this.#motionQuery()?.matches);
  }

  #motionQuery() {
    return window.matchMedia?.('(prefers-reduced-motion: reduce)');
  }

  #number(value, fallback) {
    const number = Number(value);
    return Number.isFinite(number) && number > 0 ? number : fallback;
  }

  #emit(name, detail) {
    this.dispatchEvent(
      new CustomEvent(name, {
        bubbles: true,
        composed: true,
        detail,
      })
    );
  }
}

if (!customElements.get('fox-marquee')) {
  customElements.define('fox-marquee', FoxMarquee);
}
